#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005
#define LOGN 18
#define INF 1000000000

typedef struct {
    int u, v, w;
} Edge;

// Comparador para ordenar arestas em ordem decrescente de peso
int cmp_edges(const void *a, const void *b) {
    Edge *e1 = (Edge *)a;
    Edge *e2 = (Edge *)b;
    return e2->w - e1->w;
}

// Estrutura DSU (Disjoint Set Union)
int parent_dsu[MAXN];

int find_set(int v) {
    if (v == parent_dsu[v])
        return v;
    return parent_dsu[v] = find_set(parent_dsu[v]);
}

void union_sets(int a, int b) {
    a = find_set(a);
    b = find_set(b);
    if (a != b) {
        parent_dsu[b] = a;
    }
}

