void add_edge(int u, int v, int w) {
    adj[edge_cnt].to = v;
    adj[edge_cnt].weight = w;
    adj[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

// Binary Lifting para LCA e peso mínimo na árvore
int depth[MAXN];
int up[MAXN][LOGN];
int min_w[MAXN][LOGN];

static inline int min_val(int a, int b) {
    return a < b ? a : b;
}

// DFS iterativa para evitar estouro de pilha de recursão caso a árvore seja uma linha
void dfs(int root, int n) {
    int *stack = (int *)malloc((n + 1) * sizeof(int));
    int *cur_edge = (int *)malloc((n + 1) * sizeof(int));
    int top = 0;

    for (int i = 1; i <= n; i++) {
        depth[i] = -1;
        cur_edge[i] = head[i];
    }

    depth[root] = 0;
    up[root][0] = root;
    min_w[root][0] = INF;
    stack[top++] = root;

    while (top > 0) {
        int u = stack[top - 1];

        if (cur_edge[u] != -1) {
            int e = cur_edge[u];
            cur_edge[u] = adj[e].next;
            int v = adj[e].to;
            int w = adj[e].weight;

            if (depth[v] == -1) {
                depth[v] = depth[u] + 1;
                up[v][0] = u;
                min_w[v][0] = w;
                stack[top++] = v;
            }
        } else {
            top--;
        }
    }

    free(stack);
    free(cur_edge);
}

