    int ans = INF;

    if (depth[u] < depth[v]) {
        int temp = u;
        u = v;
        v = temp;
    }

    // Igualar as profundidades
    for (int k = LOGN - 1; k >= 0; k--) {
        if (depth[u] - (1 << k) >= depth[v]) {
            ans = min_val(ans, min_w[u][k]);
            u = up[u][k];
        }
    }

    if (u == v) return ans;

    for (int k = LOGN - 1; k >= 0; k--) {
        if (up[u][k] != up[v][k]) {
            ans = min_val(ans, min_w[u][k]);
            ans = min_val(ans, min_w[v][k]);
            u = up[u][k];
            v = up[v][k];
        }
    }

    ans = min_val(ans, min_w[u][0]);
    ans = min_val(ans, min_w[v][0]);

    return ans;
