        int v = edges[i].v;
        int w = edges[i].w;

        if (find_set(u) != find_set(v)) {
            union_sets(u, v);
            add_edge(u, v, w);
            add_edge(v, u, w);
            mst_edges++;
            if (mst_edges == n - 1) break;
        }
    }
    free(edges);

    // Pré-computação com Binary Lifting
    dfs(1, n);

    for (int k = 1; k < LOGN; k++) {
        for (int i = 1; i <= n; i++) {
            up[i][k] = up[up[i][k - 1]][k - 1];
            min_w[i][k] = min_val(min_w[i][k - 1], min_w[up[i][k - 1]][k - 1]);
        }
    }

    int c;
    if (scanf("%d", &c) != 1) return 0;

    while (c--) {
        int u, v;
        scanf("%d %d", &u, &v);
        printf("%d\n", query(u, v));
    }

    return 0;
}
